-- Extensions, schemas and enum types
create extension if not exists "uuid-ossp" with schema extensions;
create schema if not exists app;
CREATE TYPE public.mood AS ENUM ('sad', 'ok');
create type app."Status" as enum ('draft', 'published');

/* A block comment /* nested */ still a comment; CREATE TABLE ghost (id int); */

BEGIN;
-- Unquoted names are folded to lower case, quoted ones are kept
CREATE TABLE Users (
    Id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Email" text NOT NULL UNIQUE,
    display_name varchar(80),
    mood public.mood DEFAULT 'ok'::public.mood,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    balance numeric(12, 2) DEFAULT 0.00 NOT NULL,
    big bigint DEFAULT 9007199254740993,
    created_at timestamp(3) with time zone DEFAULT now() NOT NULL,
    profile jsonb DEFAULT '{"theme": "dark"}'::jsonb,
    note text COLLATE "C" CHECK (char_length(note) < 500),
    search tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(display_name, ''))) STORED,
    fulltext text,
    key text,
    index integer
);
COMMIT;

CREATE TABLE app.posts (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    author_id bigint NOT NULL REFERENCES public.users (id) ON DELETE CASCADE,
    parent_id uuid,
    status app."Status" NOT NULL DEFAULT 'draft',
    title text NOT NULL,
    slug text,
    body text,
    CONSTRAINT posts_pkey PRIMARY KEY (id),
    CONSTRAINT posts_parent_fkey FOREIGN KEY (parent_id) REFERENCES app.posts (id) ON DELETE SET NULL ON UPDATE CASCADE DEFERRABLE INITIALLY DEFERRED,
    UNIQUE (author_id, slug)
);
CREATE INDEX posts_title_lower_idx ON app.posts USING btree (lower(title));
CREATE UNIQUE INDEX IF NOT EXISTS posts_slug_published ON app.posts (slug) WHERE status = 'published';
COMMENT ON COLUMN app.posts.title IS 'The title; shown in lists';
COMMENT ON TABLE app.posts IS 'Posts';

-- A function: its body has semicolons and DDL that does not run here
CREATE OR REPLACE FUNCTION public.touch() RETURNS trigger LANGUAGE plpgsql AS $body$
BEGIN
  NEW.updated_at := now(); -- ;
  EXECUTE 'CREATE TABLE never_created (id int)';
  RETURN NEW;
END;
$body$;
CREATE TRIGGER users_touch BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION public.touch();
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users read themselves" ON public.users FOR SELECT TO authenticated USING (true);
GRANT SELECT ON public.users TO anon;
REVOKE ALL ON app.posts FROM anon;
ALTER TABLE app.posts OWNER TO postgres;
CREATE VIEW public.user_names AS SELECT id, display_name FROM public.users;
CREATE MATERIALIZED VIEW public.post_counts AS SELECT author_id, count(*) AS posts FROM app.posts GROUP BY author_id;
CREATE UNIQUE INDEX post_counts_author ON public.post_counts (author_id);
